29	// 不依赖文件修改时间，也不信任受损记录文件里读出的父标识或槽首标记。
30	//
31	// 旧版本写出的指针没有 History 字段；读取时会在内存中按校验通过的父链
32	// 回退重建，不要求用户转换数据。
33	type slotPointer struct {
34		Latest  RecordID   `json:"latest"`
35		History []RecordID `json:"history,omitempty"`
36	}
37	
38	// archiveMarker 是存档目录的标记文件。
39	type archiveMarker struct {
40		Format int `json:"format"`
41	}
42	
43	// Archive 是一个本地存档目录句柄。多个进程或多个实例可以同时打开
44	// 同一目录；所有写入通过目录内的 flock 串行化。
45	type Archive struct {
46		dir string
47	}
48	
49	const (
50		markerName  = "archive.json"
51		recordsName = "records"
52		slotsName   = "slots"
53	)
54	
55	// Create 在指定目录建立新的存档。目录会被创建；若该目录已经是一个
56	// 存档则返回错误，以免覆盖已有数据。
57	//
58	// 创建有明确的结果：要么完整成功并返回可立即使用的句柄，要么返回
59	// 错误且不返回句柄。准备必要目录、写入存档标记或建立锁文件时出错，
60	// 都会把指明失败操作与位置的错误交给调用方，并撤回本次创建已产生的
61	// 标记、锁文件与子目录——回退只限本次新增的内容：目录里原有的文件与
62	// 子目录（包括原本就存在、可直接使用的空 records/slots 子目录）以及
63	// 调用前已存在的目标目录本身都保持原样。因此失败后排除障碍即可用
64	// 同一路径重新创建，不会被上一次失败留下的标记拒绝。
65	func Create(dir string) (_ *Archive, err error) {
66		// 本次调用新产生的内容，失败时按相反顺序撤回；调用前已存在的
67		// 任何内容都不在撤回范围内。
68		var created []string
69		defer func() {
70			if err != nil {
71				for i := len(created) - 1; i >= 0; i-- {
72					os.Remove(created[i])
73				}
74			}
75		}()
76	
77		// 目标目录在调用前已存在时保留它（包括失败回退时）；不存在才
78		// 由本次创建建立，并纳入回退范围。
79		if _, statErr := os.Stat(dir); statErr != nil {
80			if !errors.Is(statErr, os.ErrNotExist) {
81				return nil, fmt.Errorf("检查存档目录 %s: %w", dir, statErr)
82			}
83			if err := os.MkdirAll(dir, 0o755); err != nil {
84				return nil, fmt.Errorf("建立存档目录 %s: %w", dir, err)
85			}
86			created = append(created, dir)
87		}
88	
89		markerPath := filepath.Join(dir, markerName)
90		f, err := os.OpenFile(markerPath, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
91		if err != nil {
92			if errors.Is(err, os.ErrExist) {
93				// 已有存档：原样保留既有标记（即使它无法解析），不覆盖，
94				// 也不借回退删除；此时本次尚未产生任何新内容。
95				return nil, &ConflictError{Reason: "目录已是一个存档: " + dir}
96			}
97			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
98		}
99		created = append(created, markerPath)
100		markerData, _ := json.Marshal(archiveMarker{Format: archiveFormatVersion})
101		if _, err := f.Write(markerData); err != nil {
102			f.Close()
103			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
104		}
105		if err := f.Close(); err != nil {
106			return nil, fmt.Errorf("写入存档标记 %s: %w", markerPath, err)
107		}
108	
109		for _, sub := range []string{recordsName, slotsName} {
110			subPath := filepath.Join(dir, sub)
111			if fi, statErr := os.Stat(subPath); statErr == nil {
112				if !fi.IsDir() {
113					return nil, fmt.Errorf("建立存档子目录 %s: 位置已被同名文件占用", subPath)
114				}
115				// 原本就存在的子目录直接沿用，回退时保留。
116				continue
117			} else if !errors.Is(statErr, os.ErrNotExist) {
118				return nil, fmt.Errorf("检查存档子目录 %s: %w", subPath, statErr)
119			}
120			if err := os.Mkdir(subPath, 0o755); err != nil {
121				return nil, fmt.Errorf("建立存档子目录 %s: %w", subPath, err)
122			}
123			created = append(created, subPath)
124		}
125	
126		// 预先建立锁文件并同步目录，使之后的打开更稳妥。锁位置已被占用
127		// （例如已是一个目录）时明确报错，而不是留到首次保存才失败。
128		lockPath := filepath.Join(dir, "lock")
129		_, lockStatErr := os.Stat(lockPath)
130		lockExisted := lockStatErr == nil
131		if lockStatErr != nil && !errors.Is(lockStatErr, os.ErrNotExist) {
132			return nil, fmt.Errorf("检查存档锁文件 %s: %w", lockPath, lockStatErr)
133		}
134		lf, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o600)
135		if err != nil {
136			return nil, fmt.Errorf("建立存档锁文件 %s: %w", lockPath, err)
137		}
138		if err := lf.Close(); err != nil {
139			return nil, fmt.Errorf("建立存档锁文件 %s: %w", lockPath, err)
140		}
141		if !lockExisted {
142			created = append(created, lockPath)
143		}
144	
145		if err := syncDir(dir); err != nil {
146			return nil, fmt.Errorf("同步存档目录 %s: %w", dir, err)
147		}
148		return &Archive{dir: dir}, nil
149	}
150	
151	// Open 打开一个此前由 Create 建立的存档目录。
152	func Open(dir string) (*Archive, error) {
153		path := filepath.Join(dir, markerName)
154		f, err := os.Open(path)
155		if err != nil {
156			if errors.Is(err, os.ErrNotExist) {
157				return nil, &NotFoundError{}
158			}
159			return nil, err
160		}
161		defer f.Close()
162		var m archiveMarker
163		if err := json.NewDecoder(f).Decode(&m); err != nil {
164			return nil, &CorruptError{Reason: "存档标记无法解析"}
165		}
166		if m.Format != archiveFormatVersion {
167			return nil, &CorruptError{Reason: "不支持的存档格式版本"}
168		}
169		for _, sub := range []string{recordsName, slotsName} {
170			if fi, err := os.Stat(filepath.Join(dir, sub)); err != nil || !fi.IsDir() {
171				return nil, &CorruptError{Reason: "存档目录结构不完整: 缺少 " + sub}
172			}
173		}
174		return &Archive{dir: dir}, nil
175	}
176	
177	// Dir 返回存档目录路径。
178	func (a *Archive) Dir() string { return a.dir }
179	
180	func (a *Archive) slotPath(slot string) string {
181		return filepath.Join(a.dir, slotsName, slot+".json")
182	}
183	
184	// validSlotName 拒绝空名以及可能逃逸 slots 目录的名字。
185	func validSlotName(slot string) bool {
186		if slot == "" || slot == "." || slot == ".." {
187			return false
188		}
189		if filepath.IsAbs(slot) {
190			return false
191		}
192		for _, r := range slot {
193			if r == '/' || r == '\\' || r == 0 {
194				return false
195			}
196		}
197		return filepath.Clean(slot) == slot
198	}
199	
200	// readSlotPointerLocked 在调用方已持锁的前提下读取并解析槽指针文件。
201	func (a *Archive) readSlotPointerLocked(slot string) (slotPointer, error) {
202		data, err := os.ReadFile(a.slotPath(slot))
203		if err != nil {
204			if errors.Is(err, os.ErrNotExist) {
205				return slotPointer{}, &NotFoundError{Slot: slot}
206			}
207			return slotPointer{}, err
208		}
209		var p slotPointer
210		if err := json.Unmarshal(data, &p); err != nil {
211			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针无法解析"}
212		}
213		if p.Latest == "" {
214			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针为空"}
215		}
216		return p, nil
217	}
218	
219	// readLatestLocked 在调用方已持锁的前提下读取槽当前最新记录标识。
220	func (a *Archive) readLatestLocked(slot string) (RecordID, error) {
221		p, err := a.readSlotPointerLocked(slot)
222		if err != nil {
223			return "", err
224		}
225		return p.Latest, nil
226	}
227	
228	// Save 在存档中保存一个世界。
229	//
230	// 首次保存会创建同名存档槽；槽名已存在时返回 *ConflictError。
231	// 成功后返回新记录的标识，记录包含完整世界数据，且没有父记录。
232	func (a *Archive) Save(slot string, w *World) (RecordInfo, error) {
233		if !validSlotName(slot) {
234			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
235		}
236		st := w.Snapshot()
237	
238		lock, err := acquireLock(a.dir)
239		if err != nil {
240			return RecordInfo{}, err
241		}
242		defer lock.release()
243	
244		// 持锁后再次确认槽不存在。
245		if _, err := a.readLatestLocked(slot); err == nil {
246			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
247		} else if !errors.As(err, new(*NotFoundError)) {
248			return RecordInfo{}, err
249		}
250	
251		id, err := newRecordID()
252		if err != nil {
253			return RecordInfo{}, err
254		}
255		env := &envelope{
256			Format:    archiveFormatVersion,
257			ID:        id,
258			SlotFirst: true,
259			State:     st,
260		}
261		env.Checksum = computeChecksum(env)
262		if err := writeRecord(a.dir, env); err != nil {
263			return RecordInfo{}, err
264		}
265		if err := a.createSlotPointer(slot, id); err != nil {
266			return RecordInfo{}, err
267		}
268		return RecordInfo{ID: id, SlotFirst: true, Version: st.Rules.Version}, nil
269	}
270	
271	// createSlotPointer 以“临时文件写全 + os.Link 原子建立”的方式创建槽
272	// 指针：Link 在目标已存在时失败，因此重名会被明确拒绝，同时崩溃后
273	// 要么没有该槽，要么指向一份完整记录，绝不会留下半写的指针。新槽的
274	// 历史索引只含其首条记录本身——分支槽不会把来源槽的记录计入候选。
275	func (a *Archive) createSlotPointer(slot string, id RecordID) error {
276		slotsDir := filepath.Join(a.dir, slotsName)
277		final := a.slotPath(slot)
278		data, _ := json.MarshalIndent(slotPointer{
279			Latest:  id,
280			History: []RecordID{id},
281		}, "", "  ")
282	
283		tmp := filepath.Join(slotsDir, ".new-"+slot+"-"+randomSuffix()+".tmp")
284		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
285		if err != nil {
286			return err
287		}
288		if _, err := f.Write(data); err != nil {
289			f.Close()
290			os.Remove(tmp)
291			return err
292		}
293		if err := f.Sync(); err != nil {
294			f.Close()
295			os.Remove(tmp)
296			return err
297		}
298		if err := f.Close(); err != nil {
299			os.Remove(tmp)
300			return err
301		}
302		if err := os.Link(tmp, final); err != nil {
303			os.Remove(tmp)
304			if errors.Is(err, os.ErrExist) {
305				return &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
306			}
307			return err
308		}
309		os.Remove(tmp)
310		return syncDir(slotsDir)
311	}
312	
313	// Replace 用世界当前状态覆盖槽的最新记录。
314	//
315	// expected 必须是调用方此前读到的记录标识，并且它仍是该槽最新记录，
316	// 写入才会发生；否则返回 *ConflictError——即使该标识对应的旧文件恰好
317	// 已损坏或被删除，过期请求也只报冲突，不改报文件错误。标识匹配时还要
318	// 确认这条当前记录本身可正常读取：文件缺失返回 *NotFoundError；截断、
319	// 校验和不匹配、世界状态不合法或父记录缺失返回 *CorruptError。绝不用
320	// 调用方传入的完整世界掩盖当前记录的问题，也不自动改选较老记录为父。
321	// 新记录的父记录就是被覆盖的那次记录。同一目录下并发覆盖同一父记录时
322	// 只有一个成功。被拒绝的覆盖不改变槽指向、历史与任何已有记录。
323	func (a *Archive) Replace(slot string, w *World, expected RecordID) (RecordInfo, error) {
324		if !validSlotName(slot) {
325			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
326		}
327		if expected == "" {
328			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "覆盖必须提供所依据的记录标识"}
329		}
330		st := w.Snapshot()
331	
332		lock, err := acquireLock(a.dir)
333		if err != nil {
334			return RecordInfo{}, err
335		}
336		defer lock.release()
337	
338		pointer, err := a.readSlotPointerLocked(slot)
339		if err != nil {
340			return RecordInfo{}, err
341		}
342		if pointer.Latest != expected {
343			return RecordInfo{}, &ConflictError{
344				Slot:   slot,
345				Reason: "所依据的记录已不是该槽最新记录",
346			}
347		}
348	
349		// 标识匹配后，当前记录本身必须可正常读取：完整、内容校验通过、
350		// 世界状态合法且父记录关系成立。否则以它为父保存的新记录随后也
351		// 无法读取，等于用调用方传入的完整世界掩盖了当前记录的问题；
352		// 这里沿用与读取路径一致的校验，损坏或缺失时拒绝覆盖，槽指向、
353		// 历史与已有记录保持原样，调用方可改走恢复预览与确认恢复。
354		if _, err := a.loadAndVerifyLocked(expected); err != nil {
355			if ce, ok := err.(*CorruptError); ok {
356				ce.Slot = slot
357			}
358			return RecordInfo{}, err
359		}
360	
361		// 覆盖保存传入世界的快照，以被覆盖的当前记录为父，沿用共同的
362		// 新记录组装、落盘与槽指针提交路径。
363		return a.appendSlotRecordLocked(slotSave{
364			slot:          slot,
365			oldPointer:    pointer,
366			parent:        expected,
367			historyAnchor: expected,
368			state:         st,
369		})
370	}
371	
372	// commitSlotPointerLocked 在记录文件已完整落盘后，原子更新槽指针：指向
373	// 新记录，并把历史索引按保存次序前置新记录。历史索引只在此刻（记录已
374	// 完整生效）才更新，因此残留临时文件与写完但未完成保存的孤儿记录绝不会
375	// 进入恢复候选。
376	func (a *Archive) commitSlotPointerLocked(slot string, oldPointer slotPointer, oldLatest, newID RecordID) error {
377		history, err := a.nextSlotHistoryLocked(oldPointer, oldLatest, newID)
378		if err != nil {
379			return err
380		}
381		return a.persistSlotPointerLocked(slot, slotPointer{Latest: newID, History: history})
382	}
383	
384	// replaceSlotPointer 直接把槽指针指向 id，不附带历史索引。它仅用于测试
385	// 中模拟旧版本或外部写入器留下的指针；生产写入路径一律走
386	// commitSlotPointerLocked 以维护历史索引。
387	func (a *Archive) replaceSlotPointer(slot string, id RecordID) error {
388		return a.persistSlotPointerLocked(slot, slotPointer{Latest: id})
389	}
390	
391	// Branch 从 srcSlot 的指定历史记录 src 分出新槽 dstSlot。
392	//
393	// 新槽的首条记录以 src 为父记录，完整复制当时的种子、规则和状态。
394	// 目标槽名已存在时返回 *ConflictError。源记录必须校验通过。
395	func (a *Archive) Branch(srcSlot string, src RecordID, dstSlot string) (RecordInfo, error) {
396		if !validSlotName(srcSlot) {
397			return RecordInfo{}, &ConflictError{Slot: srcSlot, Reason: "非法源存档槽名"}
398		}
399		if !validSlotName(dstSlot) {
400			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "非法目标存档槽名"}
401		}
402		if src == "" {
403			return RecordInfo{}, &NotFoundError{Slot: srcSlot}
404		}
405	
406		lock, err := acquireLock(a.dir)
407		if err != nil {
408			return RecordInfo{}, err
409		}
410		defer lock.release()
411	
412		srcEnv, err := a.loadAndVerifyLocked(src)
413		if err != nil {
414			return RecordInfo{}, err
415		}
416		// 确认源记录确实属于源槽的历史链，避免拿别的槽的记录冒充分支源。
417		if err := a.assertInSlotHistoryLocked(srcSlot, src); err != nil {
418			return RecordInfo{}, err
419		}
420		// 目标槽重名拒绝创建。
421		if _, err := a.readLatestLocked(dstSlot); err == nil {
422			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "目标存档槽名已存在"}
423		} else if !errors.As(err, new(*NotFoundError)) {
424			return RecordInfo{}, err
425		}
426	
427		id, err := newRecordID()
428		if err != nil {
429			return RecordInfo{}, err
430		}
431		env := &envelope{
432			Format:    archiveFormatVersion,
433			ID:        id,
434			Parent:    src,
435			SlotFirst: true,
436			// 完整复制当时的世界数据；此后两槽各自保存互不影响。
437			State: cloneState(srcEnv.State),
438		}
439		env.Checksum = computeChecksum(env)
440		if err := writeRecord(a.dir, env); err != nil {
441			return RecordInfo{}, err
442		}
443		if err := a.createSlotPointer(dstSlot, id); err != nil {
444			return RecordInfo{}, err
445		}
446		return RecordInfo{
447			ID:        id,
448			Parent:    src,
449			SlotFirst: true,
450			Version:   env.State.Rules.Version,
451		}, nil
452	}
453	
454	// assertInSlotHistoryLocked 确认 id 位于 slot 自身的历史次序中（分支槽
455	// 的历史只含它自己保存成功的记录，不含来源槽记录）。
456	func (a *Archive) assertInSlotHistoryLocked(slot string, id RecordID) error {
457		history, err := a.slotHistoryLocked(slot)
458		if err != nil {
459			return err
460		}
461		for _, cid := range history {
462			if cid == id {
463				return nil
464			}
465		}
466		return &NotFoundError{Slot: slot, Record: id}
467	}
468	
469	// slotHistoryLocked 返回该槽按保存生效次序排列的记录标识（最新在前、
470	// 槽首记录在末尾）。
471	//
472	// 优先使用指针内嵌的历史索引；旧版本指针没有该索引时，在内存中沿
473	// “校验通过”的记录父链回退重建，绝不在读取路径上改写目录。重建在缺失、
474	// 无法解析或校验不过的记录处停止——无法确认归属的更老记录不再使用。
475	// 槽首标记只取自校验通过的信封，因此受损记录里被篡改的父标识或槽首
476	// 标记既不能把遍历引向别的槽，也不能遮住本槽更早的可用记录。
477	func (a *Archive) slotHistoryLocked(slot string) ([]RecordID, error) {
478		p, err := a.readSlotPointerLocked(slot)
479		if err != nil {
480			return nil, err
481		}
482		if len(p.History) > 0 {
483			// 以 Latest 为链头做一次去重规范化，容忍索引中的重复项。
484			return dedupeRecordIDs(append([]RecordID{p.Latest}, p.History...)), nil
485		}
486		return a.rebuildHistoryLocked(p.Latest)
487	}
488	
489	// rebuildHistoryLocked 从 latest 起沿校验通过的父链在内存中重建历史，
490	// 只返回仍能确认属于本槽的记录；在缺失、无法解析或校验不过的记录处停止。
491	func (a *Archive) rebuildHistoryLocked(latest RecordID) ([]RecordID, error) {
492		var chain []RecordID
493		seen := map[RecordID]bool{}
494		cur := latest
495		for cur != "" {
496			if seen[cur] {
497				return nil, &CorruptError{Record: cur, Reason: "历史链出现环"}
498			}
499			seen[cur] = true
500			env, err := a.loadAndVerifyLocked(cur)
501			if err != nil {
502				// 缺失、无法解析或校验不过：无法继续确认更老记录的归属，
503				// 旧历史在此断裂；已确认的部分仍可使用。
504				return chain, nil
505			}
506			chain = append(chain, cur)
507			if env.SlotFirst {
508				return chain, nil
509			}
510			cur = env.Parent
511		}
512		return chain, nil
513	}
514	
515	// dedupeRecordIDs 按首次出现次序去重记录标识。
516	func dedupeRecordIDs(ids []RecordID) []RecordID {
517		seen := map[RecordID]bool{}
518		out := ids[:0]
519		for _, id := range ids {
520			if id == "" || seen[id] {
521				continue
522			}
523			seen[id] = true
524			out = append(out, id)
525		}
526		return out
527	}
528	
529	// persistSlotPointerLocked 以原子改名写出槽指针。
530	func (a *Archive) persistSlotPointerLocked(slot string, p slotPointer) error {
531		data, _ := json.MarshalIndent(p, "", "  ")
532		return writeAtomic(filepath.Join(a.dir, slotsName), slot+".json", data)
533	}
534	
535	// nextSlotHistory 在一次以 oldLatest 为被覆盖/升级记录的成功写入后，
536	// 生成新指针应持有的历史次序：新记录在最前，其余沿用此前已确认属于
537	// 本槽的记录。旧指针无索引时在内存中回退重建（不完整也照样承接），
538	// 从而让旧历史在第一次成功覆盖或升级后获得完整恢复能力。
539	func (a *Archive) nextSlotHistoryLocked(oldPointer slotPointer, oldLatest, newID RecordID) ([]RecordID, error) {
540		base := oldPointer.History
541		if len(base) == 0 {
542			rebuilt, err := a.rebuildHistoryLocked(oldLatest)
543			if err != nil {
544				return nil, err
545			}
546			base = rebuilt
547		}
548		return dedupeRecordIDs(append([]RecordID{newID}, base...)), nil
549	}
550	
551	// Slots 返回所有存档槽名。
552	func (a *Archive) Slots() ([]string, error) {
553		entries, err := os.ReadDir(filepath.Join(a.dir, slotsName))
554		if err != nil {
555			return nil, err
556		}
557		var names []string
558		for _, e := range entries {
559			if e.IsDir() {
560				continue
561			}
562			name := e.Name()
563			if len(name) > 5 && name[len(name)-5:] == ".json" {
564				names = append(names, name[:len(name)-5])
565			}
566		}
567		return names, nil
568	}
