1	package world
2	
3	import (
4		"fmt"
5		"math/big"
6		"sort"
7	)
8	
9	// BlockerKind 表示升级阻碍的类型。
10	type BlockerKind string
11	
12	const (
13		// BlockerLocation 表示角色所在地点在目标规则中已不存在。
14		BlockerLocation BlockerKind = "location"
15		// BlockerItem 表示角色携带的某种物品在目标规则中已不被允许。
16		BlockerItem BlockerKind = "item"
17		// BlockerLimit 表示角色携带总量超过目标规则给出的上限。
18		BlockerLimit BlockerKind = "limit"
19	)
20	
21	// Blocker 描述一条“目标规则无法原样承接当前角色状态”的具体阻碍。
22	type Blocker struct {
23		// Character 是受阻碍的角色标识。
24		Character string
25		// Kind 是阻碍类型。
26		Kind BlockerKind
27		// Location 是缺失的地点（Kind 为 BlockerLocation 时有值）。
28		Location string
29		// Item 是被移除的物品种类（Kind 为 BlockerItem 时有值）。
30		Item string
31		// Total 是角色当前携带总量（Kind 为 BlockerLimit 且 TotalOverflow
32		// 为 false 时有值，此时它就是真实总量）。
33		Total int
34		// TotalOverflow 表示真实携带总量超出 int 能表示的范围（来源规则未设
35		// 上限时可能出现）：此时 Total 不代表实际总量，调用方应改用
36		// TotalText 给出的完整十进制真实总量。
37		TotalOverflow bool
38		// TotalText 是真实携带总量的完整十进制表示（仅 TotalOverflow 为
39		// true 时有值）。
40		TotalText string
41		// Limit 是目标规则给出的新上限（Kind 为 BlockerLimit 时有值）。
42		Limit int
43	}
44	
45	// UpgradeCheck 描述对槽当前最新记录与目标规则的兼容性检查结果。
46	type UpgradeCheck struct {
47		// RecordID 是所检查的来源记录标识（槽当前最新记录）。
48		RecordID RecordID
49		// OldVersion 是来源记录的规则版本。
50		OldVersion string
51		// TargetVersion 是目标规则版本。
52		TargetVersion string
53		// Compatible 表示目标规则能否原样承接当前角色状态。
54		Compatible bool
55		// Blockers 是全部阻碍，按角色标识、物品标识排序；重复检查输出顺序一致。
56		Blockers []Blocker
57	}
58	
59	// UpgradeResult 是升级的返回结果。
60	type UpgradeResult struct {
61		// Check 是对当前来源记录与目标规则的兼容性检查结果。
62		Check UpgradeCheck
63		// Record 是成功时新记录的元信息；被阻碍时为零值。
64		Record RecordInfo
65	}
66	
67	// checkCompatibility 计算用 target 规则原样承接 st 中全部角色状态的阻碍。
68	//
69	// 兼容只判断能否原样承接当前角色状态：每个角色所在地点仍存在，已列出的
70	// 物品种类仍被允许（数量为零也算），各角色携带总量不超过目标上限（按真实
71	// 总量精确求和，不因回绕放过超限；真实总量超出 int 范围时阻碍置
72	// TotalOverflow 并以 TotalText 给出完整十进制总量）；目标中没有该角色上限
73	// 时表示不设上限。允许删去无人所在的地点、不再出现的物品种类或旧连通关系，
74	// 也允许增加内容。升级后移动和物品变化按目标规则处理。
75	func checkCompatibility(st State, target Rules) []Blocker {
76		locSet := make(map[string]struct{}, len(target.Locations))
77		for _, l := range target.Locations {
78			locSet[l] = struct{}{}
79		}
80		kindSet := make(map[string]struct{}, len(target.ItemKinds))
81		for _, k := range target.ItemKinds {
82			kindSet[k] = struct{}{}
83		}
84		var blockers []Blocker
85		for _, ch := range st.Characters {
86			if _, ok := locSet[ch.Location]; !ok {
87				blockers = append(blockers, Blocker{
88					Character: ch.ID,
89					Kind:      BlockerLocation,
90					Location:  ch.Location,
91				})
92			}
93			total := new(big.Int)
94			for _, it := range ch.Items {
95				if _, ok := kindSet[it.Item]; !ok {
96					blockers = append(blockers, Blocker{
97						Character: ch.ID,
98						Kind:      BlockerItem,
99						Item:      it.Item,
100					})
101				}
102				total.Add(total, bigInt(it.Count))
103			}
104			// 携带上限按真实总量判断：精确求和，不因加法回绕而放过超限。
105			// 真实总量能用 int 表示时沿用 Total 字段；超出 int 范围时置
106			// TotalOverflow 并给出完整十进制 TotalText。
107			if limit, ok := target.CarryLimits[ch.ID]; ok && total.Cmp(bigInt(limit)) > 0 {
108				b := Blocker{
109					Character: ch.ID,
110					Kind:      BlockerLimit,
111					Limit:     limit,
112				}
113				if total.Cmp(maxIntBig) <= 0 {
114					b.Total = int(total.Int64())
115				} else {
116					b.TotalOverflow = true
117					b.TotalText = total.String()
118				}
119				blockers = append(blockers, b)
120			}
121		}
122		// 同类问题按角色标识、物品标识排序；location/limit 阻碍没有物品标识，
123		// 以空物品标识参与排序，保证重复检查输出顺序一致。跨类别按
124		// location、item、limit 的自然顺序分组，便于阅读。
125		kindRank := func(k BlockerKind) int {
126			switch k {
127			case BlockerLocation:
128				return 0
129			case BlockerItem:
130				return 1
131			case BlockerLimit:
132				return 2
133			}
134			return 3
135		}
136		sort.SliceStable(blockers, func(i, j int) bool {
137			if blockers[i].Character != blockers[j].Character {
138				return blockers[i].Character < blockers[j].Character
139			}
140			if blockers[i].Kind != blockers[j].Kind {
141				return kindRank(blockers[i].Kind) < kindRank(blockers[j].Kind)
142			}
143			return blockers[i].Item < blockers[j].Item
144		})
145		return blockers
146	}
147	
148	// checkUpgradeLocked 在调用方已持锁（共享或排他均可）的前提下读取并校验
149	// 槽当前最新记录，计算目标规则的兼容性。返回检查结果与来源记录信封。
150	func (a *Archive) checkUpgradeLocked(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, *envelope, error) {
151		latest, err := a.readLatestLocked(slot)
152		if err != nil {
153			return UpgradeCheck{}, nil, err
154		}
155		env, err := a.loadAndVerifyLocked(latest)
156		if err != nil {
157			if ce, ok := err.(*CorruptError); ok {
158				ce.Slot = slot
159			}
160			return UpgradeCheck{}, nil, err
161		}
162		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
163			return UpgradeCheck{}, nil, &VersionRejectedError{
164				Slot:     slot,
165				Record:   latest,
166				Version:  env.State.Rules.Version,
167				Accepted: append([]string(nil), acceptedVersions...),
168			}
169		}
170		if target.Version == env.State.Rules.Version {
171			return UpgradeCheck{}, nil, &RuleError{Reason: "目标规则版本必须与来源记录版本不同"}
172		}
173		check := UpgradeCheck{
174			RecordID:      latest,
175			OldVersion:    env.State.Rules.Version,
176			TargetVersion: target.Version,
177		}
178		blockers := checkCompatibility(env.State, target)
179		check.Compatible = len(blockers) == 0
180		check.Blockers = blockers
181		return check, env, nil
182	}
183	
184	// CheckUpgrade 检查槽当前最新记录能否在目标规则下继续使用。
185	//
186	// 检查只读取来源记录并计算兼容性，不改变世界、历史或槽当前记录，也不会
187	// 替换记录中的规则。target 必须先满足规则自身的合法性要求，且版本与来源
188	// 记录不同（版本只按相等判断，不按数字大小限制升级）。
189	//
190	// 目标规则非法返回 *RuleError；版本相同返回 *RuleError；来源损坏返回
191	// *CorruptError；来源版本不在 acceptedVersions 内返回 *VersionRejectedError；
192	// 槽不存在沿用现有不存在错误。
193	func (a *Archive) CheckUpgrade(slot string, acceptedVersions []string, target Rules) (UpgradeCheck, error) {
194		if !validSlotName(slot) {
195			return UpgradeCheck{}, &NotFoundError{Slot: slot}
196		}
197		if err := validateRules(target); err != nil {
198			return UpgradeCheck{}, err
199		}
200		lock, err := acquireSharedLock(a.dir)
201		if err != nil {
202			return UpgradeCheck{}, err
203		}
204		defer lock.release()
205		check, _, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
206		if err != nil {
207			return UpgradeCheck{}, err
208		}
209		return check, nil
210	}
211	
212	// Upgrade 在检查通过后用目标规则生成一条新记录。
213	//
214	// 传入与 CheckUpgrade 相同的条件，并带调用方预期的最新记录标识 expected。
215	// 提交时在排他锁下重新判断当前来源：仍有阻碍则返回相同的阻碍信息并拒绝
216	// 写入；expected 为空或已不是该槽最新记录时返回现有冲突错误。
217	//
218	// 被拒绝的升级不增加历史记录，也不改变槽当前记录。成功后槽增加一条完整
219	// 的新记录，以被升级记录为父，保存目标规则；种子、时间片、角色位置及
220	// 物品数量和排列保持原样。并发升级或升级与普通覆盖竞争时，只有 expected
221	// 与最新记录一致的一个成功，其余收到冲突。
222	func (a *Archive) Upgrade(slot string, acceptedVersions []string, target Rules, expected RecordID) (UpgradeResult, error) {
223		if !validSlotName(slot) {
224			return UpgradeResult{}, &NotFoundError{Slot: slot}
225		}
226		if err := validateRules(target); err != nil {
227			return UpgradeResult{}, err
228		}
229		if expected == "" {
230			return UpgradeResult{}, &ConflictError{Slot: slot, Reason: "升级必须提供所依据的记录标识"}
231		}
232		lock, err := acquireLock(a.dir)
233		if err != nil {
234			return UpgradeResult{}, err
235		}
236		defer lock.release()
237	
238		oldPointer, err := a.readSlotPointerLocked(slot)
239		if err != nil {
240			return UpgradeResult{}, err
241		}
242		latest := oldPointer.Latest
243		if latest != expected {
244			return UpgradeResult{}, &ConflictError{
245				Slot:   slot,
246				Reason: "所依据的记录已不是该槽最新记录",
247			}
248		}
249	
250		check, env, err := a.checkUpgradeLocked(slot, acceptedVersions, target)
251		if err != nil {
252			return UpgradeResult{}, err
253		}
254		if !check.Compatible {
255			return UpgradeResult{Check: check}, &RuleError{
256				Reason: fmt.Sprintf("升级被阻碍: 目标规则无法承接当前角色状态（%d 处阻碍）", len(check.Blockers)),
257			}
258		}
259	
260		// 升级保存目标规则，种子、时间片、角色位置及物品数量和排列原样保留；
261		// 以被升级记录为父，沿用共同的新记录组装、落盘与槽指针提交路径。
262		newState := State{
263			Seed:       env.State.Seed,
264			Rules:      cloneRules(target),
265			Time:       env.State.Time,
266			Characters: cloneCharacters(env.State.Characters),
267		}
268		info, err := a.appendSlotRecordLocked(slotSave{
269			slot:          slot,
270			oldPointer:    oldPointer,
271			parent:        expected,
272			historyAnchor: latest,
273			state:         newState,
274		})
275		if err != nil {
276			return UpgradeResult{}, err
277		}
278		return UpgradeResult{Check: check, Record: info}, nil
279	}
