1	package world
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"path/filepath"
8		"strings"
9		"testing"
10	)
11	
12	// rewriteRecordTime 把已有记录的时间片改写为给定值并重算内容校验和，
13	// 模拟一份可正常解析、校验和匹配、父记录存在但时间片非法的存档记录。
14	func rewriteRecordTime(t *testing.T, a *Archive, id RecordID, time int) {
15		t.Helper()
16		path := recordPath(a.dir, id)
17		env, err := loadRecord(path)
18		if err != nil {
19			t.Fatal(err)
20		}
21		env.State.Time = time
22		env.Checksum = computeChecksum(env)
23		data, err := json.MarshalIndent(env, "", "  ")
24		if err != nil {
25			t.Fatal(err)
26		}
27		if err := os.WriteFile(path, data, 0o600); err != nil {
28			t.Fatal(err)
29		}
30	}
31	
32	// forgeNegativeTimeLatest 写入一条校验和正确但时间片为负的记录（父记录为
33	// 槽当前最新记录），并把它按正常保存路径提交为槽的最新记录。
34	func forgeNegativeTimeLatest(t *testing.T, a *Archive, slot string, time int) RecordID {
35		t.Helper()
36		p, err := a.readSlotPointerLocked(slot)
37		if err != nil {
38			t.Fatal(err)
39		}
40		st := baseWorld(t).Snapshot()
41		st.Time = time
42		id := writeRawRecord(t, a, p.Latest, false, st)
43		updatePointer(t, a, slot, id)
44		return id
45	}
46	
47	// assertNegativeTimeCorrupt 断言 err 是保留了被拒绝记录标识、且说明时间片
48	// 为负的 *CorruptError（而不是版本拒绝或其它错误）。
49	func assertNegativeTimeCorrupt(t *testing.T, err error, id RecordID) {
50		t.Helper()
51		ce, ok := err.(*CorruptError)
52		if !ok {
53			t.Fatalf("应为 *CorruptError，得到 %T: %v", err, err)
54		}
55		if ce.Record != id {
56			t.Fatalf("CorruptError 应保留被拒绝的记录标识 %s，得到 %q", id, ce.Record)
57		}
58		if !strings.Contains(ce.Error(), "时间片为负") {
59			t.Fatalf("错误应说明时间片为负: %v", ce)
60		}
61		if errors.As(err, new(*VersionRejectedError)) {
62			t.Fatalf("负时间片不应报成版本拒绝: %v", err)
63		}
64	}
65	
66	// recordFileBytes 读取记录文件的原始字节。
67	func recordFileBytes(t *testing.T, a *Archive, id RecordID) []byte {
68		t.Helper()
69		data, err := os.ReadFile(recordPath(a.dir, id))
70		if err != nil {
71			t.Fatal(err)
72		}
73		return data
74	}
75	
76	// recordCount 返回 records 目录中的记录文件数。
77	func recordCount(t *testing.T, a *Archive) int {
78		t.Helper()
79		entries, err := os.ReadDir(filepath.Join(a.dir, recordsName))
80		if err != nil {
81			t.Fatal(err)
82		}
83		return len(entries)
84	}
85	
86	// TestLatestAndRecordNegativeTimeCorrupt 校验和匹配、父记录存在、版本也在
87	// 可接受集合内，但时间片为负的记录仍属损坏：Latest 与 Record 都返回保留
88	// 记录标识并说明时间片为负的 *CorruptError，不按版本拒绝处理，也不把
89	// 时间改成零；读取保持只读，不修补这份记录。
90	func TestLatestAndRecordNegativeTimeCorrupt(t *testing.T) {
91		a, _ := newTestArchive(t)
92		ids := saveN(t, a, "s", 2) // r2 r1 r0
93		neg := forgeNegativeTimeLatest(t, a, "s", -3)
94	
95		before := recordFileBytes(t, a, neg)
96	
97		_, err := a.Latest("s", []string{"v1"})
98		assertNegativeTimeCorrupt(t, err, neg)
99	
100		_, err = a.Record("s", neg, []string{"v1"})
101		assertNegativeTimeCorrupt(t, err, neg)
102	
103		// 重复读取仍报损坏：记录没有被悄悄修补，文件字节保持原样。
104		if _, err := a.Latest("s", []string{"v1"}); err == nil {
105			t.Fatal("损坏记录不应被读取修补")
106		}
107		if got := recordFileBytes(t, a, neg); string(got) != string(before) {
108			t.Fatal("读取改写了损坏记录")
109		}
110	
111		// 本槽更早的合法记录不受影响，仍可正常读取。
112		rec, err := a.Record("s", ids[0], []string{"v1"})
113		if err != nil {
114			t.Fatalf("合法历史记录应可读: %v", err)
115		}
116		if rec.State.Time != 2 {
117			t.Fatalf("合法记录时间片应为 2，得到 %d", rec.State.Time)
118		}
119	}
120	
121	// TestRecoverSkipsNegativeTime 恢复读取与恢复预览按本槽保存次序越过时间片
122	// 为负的记录，选中最近一份时间合法、其余校验通过且版本可接受的记录；预览
123	// 的当前标识仍是槽实际指向的（损坏）记录，来源标识对应选中的完好记录。
124	func TestRecoverSkipsNegativeTime(t *testing.T) {
125		a, _ := newTestArchive(t)
126		ids := saveN(t, a, "s", 2) // r2(time 2) r1 r0
127		neg := forgeNegativeTimeLatest(t, a, "s", -1)
128	
129		rec, err := a.RecoverLatest("s", []string{"v1"})
130		if err != nil {
131			t.Fatalf("应越过负时间片记录恢复: %v", err)
132		}
133		if rec.ID != ids[0] || rec.State.Time != 2 {
134			t.Fatalf("应恢复 %s（时间片 2），得到 %s（时间片 %d）", ids[0], rec.ID, rec.State.Time)
135		}
136	
137		pv, err := a.PreviewRecovery("s", []string{"v1"})
138		if err != nil {
139			t.Fatalf("预览应越过负时间片记录: %v", err)
140		}
141		if pv.Current != neg {
142			t.Fatalf("预览当前标识应是槽实际指向的 %s，得到 %s", neg, pv.Current)
143		}
144		if pv.Source != ids[0] || pv.State.Time != 2 {
145			t.Fatalf("预览来源应是 %s（时间片 2），得到 %s（时间片 %d）", ids[0], pv.Source, pv.State.Time)
146		}
147	
148		// 负时间片记录没有被修补：再次恢复结果一致，Latest 仍报损坏。
149		if _, err := a.Latest("s", []string{"v1"}); err == nil {
150			t.Fatal("恢复/预览不应修补损坏记录")
151		}
152		rec2, err := a.RecoverLatest("s", []string{"v1"})
153		if err != nil || rec2.ID != ids[0] {
154			t.Fatalf("重复恢复结果应一致: %+v err=%v", rec2, err)
155		}
156	}
157	
158	// TestRecoverAllNegativeTimeUnrecoverable 本槽没有任何时间合法的完好记录
159	// 时，恢复读取与恢复预览都返回可由 errors.Is 判断的 ErrUnrecoverable。
160	func TestRecoverAllNegativeTimeUnrecoverable(t *testing.T) {
161		a, _ := newTestArchive(t)
162		info := saveBase(t, a, "s")
163		rewriteRecordTime(t, a, info.ID, -7)
164	
165		if _, err := a.RecoverLatest("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
166			t.Fatalf("唯一记录时间片为负应不可恢复，得到 %T: %v", err, err)
167		}
168		if _, err := a.PreviewRecovery("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
